mapper.select:
SELECT fm.id, fm.data_set_id, ds.category_id, fm.task_id, fm.original_name, fm.storage_name, fm.storage_key,
fm.extension, fm.size_bytes, fm.sha256, fm.uploaded_by, fm.upload_status, fm.error_message, fm.create_time, fm.update_time, fm.deleted FROM ocean_gis.gis_file_meta fm LEFT JOIN ocean_gis.gis_data_set ds ON ds.id = fm.data_set_id WHERE fm.deleted = 1
AND fm.data_set_id = #{dataSetId}
AND ds.category_id = #{categoryId}
AND fm.task_id = #{taskId}
AND fm.original_name LIKE CONCAT('%', #{originalName}, '%')
AND fm.extension = #{extension}
AND fm.upload_status = #{uploadStatus}
ORDER BY fm.create_time DESC
